"""Demo: deformation invariance of the activation boundary.

Evaluates several distinct zero-reflecting response laws on the excess above a
common threshold c and confirms they all vanish exactly for x <= c and are
strictly positive for x > c -- the boundary does not depend on the response law.
"""
from __future__ import annotations
import math
from typing import Callable, List, Tuple

def excess(c: float, x: float) -> float:
    return max(x - c, 0.0)

def deformed_coherence(F: Callable[[float], float], c: float, x: float) -> float:
    return F(excess(c, x))

def main() -> None:
    c: float = 10000.0
    responses: List[Tuple[str, Callable[[float], float]]] = [
        ("linear",  lambda y: y),
        ("sqrt",    lambda y: y ** 0.5),
        ("square",  lambda y: y ** 2),
        ("log1p",   lambda y: math.log1p(y)),
        ("tanh",    lambda y: math.tanh(y)),
    ]
    for dx in (-100.0, -1.0, 0.0, 1.0, 100.0):
        x = c + dx
        vals = {name: deformed_coherence(F, c, x) for name, F in responses}
        active = all(v > 0 for v in vals.values())
        zero = all(v == 0 for v in vals.values())
        status = "all > 0" if active else ("all = 0" if zero else "MIXED")
        print(f"x-c={dx:>7}: {status}")

if __name__ == "__main__":
    main()

"""Demo: the cyclotomic prime-conductor phase diagram.

Scans prime conductors around the critical cutoff p = 10001 and prints the
connection count C(p) = p - 1 together with the square-root order parameter,
showing coherence is strictly positive exactly when p > 10001.
"""
from __future__ import annotations
import math
from typing import List

CRITICAL_EDGES: int = 10000

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True

def sqrt_coherence(kappa: float, c: float, x: float) -> float:
    return math.sqrt(kappa) * math.sqrt(max(x - c, 0.0))

def main() -> None:
    primes: List[int] = [p for p in range(9950, 10060) if is_prime(p)]
    for p in primes:
        cnt = p - 1
        val = sqrt_coherence(1.0, float(CRITICAL_EDGES), float(cnt))
        status = "ACTIVE" if p > 10001 else "inactive"
        print(f"p={p:>6}  C(p)={cnt:>6}  Phi={val:8.4f}  [{status}]")

if __name__ == "__main__":
    main()

