function EULER_TOTIENT(n):
    require n >= 1
    result <- n;  m <- n;  p <- 2
    while p*p <= m:
        if p divides m:
            while p divides m: m <- m / p
            result <- result - result / p
        p <- p + 1
    if m > 1:
        result <- result - result / m
    return result        # = C(n) = phi(n)

