from __future__ import annotations

def euler_totient(n: int) -> int:
    """Return Euler's totient phi(n) via trial-division factorization.

    The cyclotomic connection count C(n) -- the number of one-dimensional complex
    representations of Gal(Q(zeta_n)/Q) -- equals phi(n).
    """
    if n <= 0:
        raise ValueError("n must be a positive integer")
    result: int = n
    m: int = n
    p: int = 2
    while p * p <= m:
        if m % p == 0:
            while m % p == 0:
                m //= p
            result -= result // p
        p += 1
    if m > 1:
        result -= result // m
    return result

def connection_count(n: int) -> int:
    """Cyclotomic connection count of conductor n."""
    return euler_totient(n)

