function ESTIMATE_EXPONENT((t1, v1), (t2, v2)):
    require t1, t2, v1, v2 > 0 and t1 != t2
    # v = t^alpha  =>  alpha = log(v2/v1) / log(t2/t1)
    return log(v2 / v1) / log(t2 / t1)
